CREATE OR REPLACE FUNCTION public.tms_records_commit(changes jsonb, reason text DEFAULT 'Edição operacional') RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; current_row public.app_records%ROWTYPE; c text; rid text; next_data jsonb; result jsonb := '[]'::jsonb; expected bigint; fiscal_doc jsonb; doc_xml xml; fiscal_value numeric; fiscal_key text; refs text[]; linked_count integer; BEGIN IF NOT public.tms_active() THEN RAISE EXCEPTION 'Usuário inativo ou não autenticado'; END IF; IF jsonb_typeof(changes) <> 'array' OR jsonb_array_length(changes)>500 THEN RAISE EXCEPTION 'Lote inválido'; END IF; FOR x IN SELECT value FROM jsonb_array_elements(changes) WHERE value->>'collection'='cteDocuments' LOOP IF coalesce((x->>'remove')::boolean,false) THEN CONTINUE; END IF; fiscal_doc:=x->'data'; doc_xml:=xmlparse(document fiscal_doc->>'xmlOriginal'); fiscal_key:=regexp_replace((xpath('string(//*[local-name()="infCte"]/@Id)',doc_xml))[1]::text,'^CTe',''); fiscal_value:=((xpath('string(//*[local-name()="vPrest"]/*[local-name()="vTPrest"])',doc_xml))[1]::text)::numeric; IF fiscal_key IS DISTINCT FROM fiscal_doc->>'chave' OR fiscal_value IS DISTINCT FROM (fiscal_doc->>'valorFiscal')::numeric OR length(fiscal_key)<>44 THEN RAISE EXCEPTION 'CT-e fiscal inválido'; END IF; SELECT array_agg(v::text) INTO refs FROM unnest(xpath('//*[local-name()="infNFe"]/*[local-name()="chave"]/text()',doc_xml)) v; IF cardinality(refs) IS NULL OR cardinality(refs)=0 THEN RAISE EXCEPTION 'CT-e sem referências de NF'; END IF; SELECT count(DISTINCT data->>'chaveNFe') INTO linked_count FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=ANY(refs); IF linked_count<>cardinality(refs) THEN RAISE EXCEPTION 'NF correspondente ainda não importada'; END IF; END LOOP; FOR x IN SELECT value FROM jsonb_array_elements(changes) ORDER BY value->>'collection',value->>'id' LOOP c:=x->>'collection'; rid:=x->>'id'; IF NOT public.tms_collection(c,CASE WHEN coalesce((x->>'remove')::boolean,false) THEN 'delete' ELSE 'write' END) THEN IF c<>'invoices' OR NOT public.tms_module('/coletas') OR coalesce((x->>'remove')::boolean,false) OR coalesce((x->>'version')::bigint,0)<>0 THEN RAISE EXCEPTION 'Sem permissão para %',c; END IF; SELECT d->'data' INTO fiscal_doc FROM jsonb_array_elements(changes) d WHERE d->>'collection'='cteDocuments' AND d->'data'->>'chave'=x->'data'->>'cteChave' AND coalesce((d->>'version')::bigint,0)=0; IF fiscal_doc IS NULL OR rid<>'REC-CTE-'||(fiscal_doc->>'chave') OR (x->'data'->>'valor')::numeric IS DISTINCT FROM (fiscal_doc->>'valorFiscal')::numeric OR x->'data'->>'status'<>'aberta' OR x->'data' ? 'movements' OR x->'data' ? 'valorRecebido' THEN RAISE EXCEPTION 'Receita deve corresponder ao CT-e novo'; END IF; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(c||':'||rid,0)); SELECT * INTO current_row FROM public.app_records WHERE collection=c AND id=rid FOR UPDATE; expected:=coalesce((x->>'version')::bigint,0); IF coalesce(current_row.version,0)<>expected THEN RAISE EXCEPTION 'CONFLICT: %/% mudou; recarregue antes de confirmar',c,rid; END IF; IF coalesce((x->>'remove')::boolean,false) THEN DELETE FROM public.app_records WHERE collection=c AND id=rid; ELSE next_data:=x->'data'; IF jsonb_typeof(next_data)<>'object' OR next_data->>'id' IS DISTINCT FROM rid THEN RAISE EXCEPTION 'Registro inválido'; END IF; IF c='orders' AND NOT public.tms_module('/financeiro') THEN next_data:=(next_data - ARRAY['costs','cteValor','divergenciaPercent','conferencia','valorNF']) || jsonb_strip_nulls(jsonb_build_object('costs',current_row.data->'costs','cteValor',current_row.data->'cteValor','divergenciaPercent',current_row.data->'divergenciaPercent','conferencia',current_row.data->'conferencia','valorNF',current_row.data->'valorNF')); IF current_row.id IS NULL THEN next_data:=next_data||jsonb_build_object('costs',jsonb_build_object('execMode','')); END IF; END IF; INSERT INTO public.app_records(collection,id,data,version,atualizado_em,atualizado_por) VALUES(c,rid,next_data,expected+1,now(),auth.uid()) ON CONFLICT(collection,id) DO UPDATE SET data=excluded.data,version=excluded.version,atualizado_em=excluded.atualizado_em,atualizado_por=excluded.atualizado_por; END IF; INSERT INTO public.tms_audit(collection,record_id,author,reason,previous_version,new_version) VALUES(c,rid,auth.uid(),reason,expected,expected+1); result:=result||jsonb_build_array(jsonb_build_object('collection',c,'id',rid,'version',expected+1)); END LOOP; RETURN result; END; $$;
CREATE OR REPLACE FUNCTION public.tms_records_read() RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.tms_active() THEN RAISE EXCEPTION 'Usuário inativo ou não autenticado'; END IF; SELECT coalesce(jsonb_agg(jsonb_build_object('collection',collection,'id',id,'version',version,'atualizado_em',atualizado_em,'data',CASE WHEN collection='orders' AND NOT public.tms_module('/financeiro') THEN (data - ARRAY['costs','cteValor','divergenciaPercent','conferencia','valorNF','valorFrete','xmlOriginal']) || jsonb_build_object('costs',jsonb_build_object('execMode',''),'valorNF',0,'valorFrete',0) WHEN collection='cteDocuments' AND NOT public.tms_module('/financeiro') THEN data - ARRAY['valorFiscal','rateio','conferencia','xmlOriginal'] ELSE data END)), '[]'::jsonb) INTO result FROM public.app_records WHERE public.tms_collection(collection,'read'); RETURN result; END; $$;
CREATE OR REPLACE FUNCTION public.tms_fiscal_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; kind_name text; owner_id text; legacy_owner text; BEGIN IF NEW.collection='orders' THEN k:=NEW.data->>'chaveNFe'; kind_name:='nfe'; ELSIF NEW.collection='cteDocuments' THEN k:=NEW.data->>'chave'; kind_name:='cte'; ELSIF NEW.collection='invoices' THEN k:=NEW.data->>'cteChave'; kind_name:='receita_cte'; ELSE RETURN NEW; END IF; IF k IS NULL OR k='' THEN RETURN NEW; END IF; IF NEW.collection='orders' THEN SELECT id INTO legacy_owner FROM public.app_records WHERE collection='orders' AND data->>'chaveNFe'=k AND id<>NEW.id LIMIT 1; ELSIF NEW.collection='cteDocuments' THEN SELECT id INTO legacy_owner FROM public.app_records WHERE (collection='cteDocuments' AND data->>'chave'=k AND id<>NEW.id) OR (collection='orders' AND data->>'cteChave'=k) LIMIT 1; ELSE SELECT id INTO legacy_owner FROM public.app_records WHERE collection='invoices' AND data->>'cteChave'=k AND id<>NEW.id LIMIT 1; END IF; IF legacy_owner IS NOT NULL THEN RAISE EXCEPTION 'Documento fiscal histórico já cadastrado; regularize pela prévia'; END IF; INSERT INTO public.tms_fiscal_keys(kind,fiscal_key,record_id) VALUES(kind_name,k,NEW.id) ON CONFLICT DO NOTHING; SELECT record_id INTO owner_id FROM public.tms_fiscal_keys WHERE kind=kind_name AND fiscal_key=k; IF owner_id<>NEW.id THEN RAISE EXCEPTION 'Documento fiscal já cadastrado: %',kind_name; END IF; RETURN NEW; END; $$;